CREATE TABLE session_meta (schema_version INTEGER NOT NULL) STRICT;
CREATE TABLE session_sessions ( id TEXT PRIMARY KEY, cwd TEXT NOT NULL, created_at TEXT NOT NULL, header_json TEXT NOT NULL CHECK(json_valid(header_json)), internal INTEGER NOT NULL, last_seq INTEGER NOT NULL, modified_at TEXT NOT NULL, message_count INTEGER NOT NULL, first_message TEXT NOT NULL CHECK(json_valid(first_message)), name TEXT CHECK(name IS NULL OR json_valid(name)), has_name INTEGER NOT NULL, summary TEXT CHECK(summary IS NULL OR json_valid(summary)), summarized_through_id TEXT, summary_state TEXT NOT NULL CHECK(json_valid(summary_state)), revision TEXT NOT NULL DEFAULT '' ) STRICT;
CREATE TABLE session_entries ( session_id TEXT NOT NULL, seq INTEGER NOT NULL, entry_id TEXT NOT NULL, entry_json TEXT NOT NULL CHECK(json_valid(entry_json)), chunks INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(session_id, seq) ) STRICT;
CREATE TABLE session_search_texts ( session_id TEXT NOT NULL, seq INTEGER NOT NULL, text_json TEXT NOT NULL CHECK(json_valid(text_json)), PRIMARY KEY(session_id, seq) ) STRICT;
CREATE TABLE session_blobs ( session_id TEXT NOT NULL, hash TEXT NOT NULL, bytes INTEGER NOT NULL, chunks INTEGER NOT NULL, PRIMARY KEY(session_id, hash) ) STRICT;
CREATE TABLE session_blob_chunks ( session_id TEXT NOT NULL, hash TEXT NOT NULL, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(session_id, hash, idx) ) STRICT;
CREATE TABLE session_entry_chunks ( session_id TEXT NOT NULL, seq INTEGER NOT NULL, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(session_id, seq, idx) ) STRICT;
CREATE TABLE session_open ( session_id TEXT NOT NULL, token TEXT NOT NULL, pid INTEGER NOT NULL, host TEXT NOT NULL, heartbeat_at INTEGER NOT NULL, schema_version INTEGER, PRIMARY KEY(session_id, token) ) STRICT;
CREATE TABLE snapshot_blobs (hash TEXT PRIMARY KEY, bytes INTEGER NOT NULL, data BLOB NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()), chunks INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE snapshot_run_refs (run_id TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY (run_id, hash)) STRICT, WITHOUT ROWID;
CREATE TABLE snapshot_run_state (run_id TEXT PRIMARY KEY, retained INTEGER NOT NULL, seq INTEGER NOT NULL) STRICT, WITHOUT ROWID;
CREATE TABLE snapshot_session_refs (session_id TEXT NOT NULL, seq INTEGER NOT NULL, root TEXT NOT NULL, snapshot_id TEXT NOT NULL, prev_seq INTEGER, restore_from TEXT, restore_to TEXT, degraded_from TEXT, degraded_since INTEGER, PRIMARY KEY (session_id, seq)) STRICT, WITHOUT ROWID;
CREATE TABLE snapshot_session_links (session_id TEXT NOT NULL, seq INTEGER NOT NULL, entry_id TEXT NOT NULL, parent_id TEXT, anchor_seq INTEGER, children INTEGER NOT NULL, broken INTEGER NOT NULL, PRIMARY KEY (session_id, seq)) STRICT;
CREATE TABLE snapshot_session_records (session_id TEXT NOT NULL, seq INTEGER NOT NULL, snapshot_id TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY (session_id, seq, hash)) STRICT, WITHOUT ROWID;
CREATE TABLE snapshot_carried_refs (owner TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY (owner, hash)) STRICT, WITHOUT ROWID;
CREATE TABLE snapshot_collection (id INTEGER PRIMARY KEY CHECK (id = 1), claimed_at INTEGER, holder TEXT, finished_at INTEGER, deleted INTEGER, error_code TEXT) STRICT;
CREATE TABLE snapshot_index_sources (source TEXT PRIMARY KEY, watermark INTEGER NOT NULL, backfilled_through INTEGER NOT NULL) STRICT, WITHOUT ROWID;
CREATE TABLE snapshot_blob_chunks (hash TEXT NOT NULL, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY (hash, idx)) STRICT;
CREATE TABLE session_search_state (sid INTEGER PRIMARY KEY, session_id TEXT NOT NULL UNIQUE, format INTEGER NOT NULL, indexed_seq INTEGER NOT NULL, revision TEXT NOT NULL, entry_id TEXT NOT NULL) STRICT;
CREATE VIRTUAL TABLE session_search_fts USING fts5(body, content='', contentless_delete=1, tokenize='trigram', detail='none');
CREATE TABLE intercom_leases( kind TEXT NOT NULL, key TEXT NOT NULL, holder_id TEXT, fencing_token INTEGER, last_token INTEGER NOT NULL, subject_json TEXT, renewed_at INTEGER, first_acquired_order INTEGER NOT NULL, PRIMARY KEY(kind, key) );
CREATE TABLE intercom_outbox( sequence INTEGER PRIMARY KEY AUTOINCREMENT, message_id TEXT NOT NULL UNIQUE, target_identity TEXT NOT NULL, origin_broker_id TEXT NOT NULL, digest TEXT NOT NULL, frame_json TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('queued', 'claimed', 'delivered', 'failed')), claim_attempts INTEGER NOT NULL DEFAULT 0, claimant_id TEXT, claim_token TEXT, claim_renewed_at INTEGER, failure_reason TEXT, settled_at INTEGER , saving_at INTEGER, queued_at INTEGER, frame_bytes INTEGER);
CREATE TABLE intercom_held_sends( "order" INTEGER PRIMARY KEY AUTOINCREMENT, message_id TEXT NOT NULL UNIQUE, reservation_key TEXT NOT NULL, origin_broker_id TEXT NOT NULL, sender_session_id TEXT NOT NULL, request_json TEXT NOT NULL, held_at INTEGER NOT NULL );
CREATE TABLE intercom_restoring_reservations( reservation_key TEXT PRIMARY KEY, "order" INTEGER NOT NULL, owner_session_id TEXT NOT NULL, owner_broker_id TEXT NOT NULL, child_name TEXT NOT NULL, child_target TEXT NOT NULL, targets_json TEXT NOT NULL, "group" TEXT NOT NULL, dormant INTEGER NOT NULL, fencing_token INTEGER NOT NULL, gone TEXT, renewed_at INTEGER NOT NULL, end_json TEXT, ended_at INTEGER , wake INTEGER NOT NULL DEFAULT 0, wake_requested INTEGER NOT NULL DEFAULT 0, wake_generation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE intercom_restoring_reservation_counters(name TEXT PRIMARY KEY, value INTEGER NOT NULL);
CREATE TABLE intercom_restoring_wake_claims( reservation_key TEXT NOT NULL, fencing_token INTEGER NOT NULL, message_id TEXT NOT NULL, PRIMARY KEY(reservation_key, fencing_token, message_id) );
CREATE TABLE intercom_pending_asks( "order" INTEGER PRIMARY KEY AUTOINCREMENT, sender_session_id TEXT NOT NULL, target_session_id TEXT NOT NULL, message_id TEXT NOT NULL, park_owner TEXT, park_key TEXT, replied INTEGER, ended_at INTEGER, UNIQUE(sender_session_id, target_session_id, message_id) );
CREATE TABLE intercom_settled_asks( sender_session_id TEXT NOT NULL, target_session_id TEXT NOT NULL, message_id TEXT NOT NULL, settled_at INTEGER NOT NULL, PRIMARY KEY(sender_session_id, target_session_id, message_id) );
CREATE TABLE intercom_released_asks( "order" INTEGER PRIMARY KEY AUTOINCREMENT, question_id TEXT NOT NULL, replier_session_id TEXT NOT NULL, asker_session_id TEXT NOT NULL, child_name TEXT NOT NULL, owner_session_id TEXT NOT NULL, state TEXT NOT NULL CHECK (state IN ('open', 'claimed', 'answered')), reply_message_id TEXT, claimed_at INTEGER, expires_at INTEGER NOT NULL, UNIQUE(question_id, replier_session_id) );
CREATE TABLE intercom_sent_messages( message_id TEXT PRIMARY KEY, digest TEXT NOT NULL, target_identity TEXT NOT NULL, question_route_json TEXT, state TEXT NOT NULL CHECK (state IN ('reserved', 'accepted')), recorded_at INTEGER NOT NULL );
CREATE TABLE intercom_known_sessions( record_order INTEGER PRIMARY KEY AUTOINCREMENT, target_identity TEXT NOT NULL UNIQUE, intercom_session_id TEXT NOT NULL, name_json TEXT, name_key TEXT, atomic_session_id TEXT, group_name TEXT NOT NULL, groups_json TEXT NOT NULL, recipient_purpose TEXT, reply_capability TEXT, recorded_at INTEGER NOT NULL , lost_at INTEGER);
CREATE TABLE intercom_session_bindings( intercom_session_id TEXT NOT NULL PRIMARY KEY, return_address TEXT NOT NULL, recorded_at INTEGER NOT NULL );
CREATE TABLE intercom_wakeups ( id INTEGER PRIMARY KEY AUTOINCREMENT, broker_id TEXT NOT NULL, reason TEXT NOT NULL CHECK (reason IN ('outbox', 'outcome')), version INTEGER NOT NULL, created_at INTEGER NOT NULL );
CREATE TABLE wf_meta(schema_version INTEGER NOT NULL);
CREATE TABLE wf_runs( run_id TEXT PRIMARY KEY, name TEXT NOT NULL, cwd TEXT NOT NULL, created_at INTEGER NOT NULL, status TEXT NOT NULL, header_json TEXT NOT NULL );
CREATE TABLE wf_events( run_id TEXT NOT NULL, seq INTEGER NOT NULL, epoch INTEGER NOT NULL, key TEXT, type TEXT NOT NULL, payload TEXT NOT NULL, at INTEGER NOT NULL, chunks INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(run_id, seq), UNIQUE(run_id, key) );
CREATE TABLE wf_leases( run_id TEXT PRIMARY KEY, holder_id TEXT, epoch INTEGER NOT NULL, renewed_at INTEGER NOT NULL );
CREATE TABLE wf_lease_builds( run_id TEXT PRIMARY KEY, holder_id TEXT NOT NULL, epoch INTEGER NOT NULL, schema_version INTEGER NOT NULL );
CREATE TABLE wf_event_chunks( run_id TEXT NOT NULL, seq INTEGER NOT NULL, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(run_id, seq, idx) ) STRICT;
CREATE TABLE wf_runs_pool_meta(version INTEGER NOT NULL);
CREATE TABLE wf_runs_pool(root TEXT PRIMARY KEY REFERENCES wf_runs(run_id) ON DELETE CASCADE, timeout INTEGER NOT NULL);
CREATE TABLE wf_runs_work( id TEXT PRIMARY KEY, root TEXT NOT NULL REFERENCES wf_runs_pool(root) ON DELETE CASCADE, boundary TEXT NOT NULL, descriptor TEXT NOT NULL, fingerprint TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'ready', generation INTEGER NOT NULL DEFAULT 0, worker TEXT, epoch INTEGER NOT NULL DEFAULT 0, expires_at INTEGER NOT NULL DEFAULT 0, renewed_at INTEGER NOT NULL DEFAULT 0, ready_at INTEGER NOT NULL, inputs_chunks INTEGER NOT NULL DEFAULT 0, UNIQUE(root, boundary) );
CREATE TABLE wf_runs_pool_session_owners( session TEXT PRIMARY KEY, work TEXT NOT NULL REFERENCES wf_runs_work(id) ON DELETE CASCADE, replay_key TEXT NOT NULL );
CREATE TABLE wf_runs_pool_operations( work TEXT NOT NULL REFERENCES wf_runs_work(id) ON DELETE CASCADE, generation INTEGER NOT NULL, operation TEXT NOT NULL, request TEXT NOT NULL, receipt TEXT NOT NULL, PRIMARY KEY(work, generation, operation) );
CREATE TABLE wf_runs_work_results( work TEXT PRIMARY KEY REFERENCES wf_runs_work(id) ON DELETE CASCADE, result TEXT NOT NULL , chunks INTEGER NOT NULL DEFAULT 0);
CREATE TABLE wf_runs_pool_control( root TEXT PRIMARY KEY REFERENCES wf_runs_pool(root) ON DELETE CASCADE, state TEXT NOT NULL DEFAULT 'running', revision INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE wf_runs_pool_usage( work TEXT NOT NULL REFERENCES wf_runs_work(id) ON DELETE CASCADE, generation INTEGER NOT NULL, key TEXT NOT NULL, input REAL NOT NULL, output REAL NOT NULL, cacheread REAL NOT NULL, cachewrite REAL NOT NULL, cost REAL NOT NULL, PRIMARY KEY(work, generation, key) );
CREATE TABLE wf_runs_pool_usage_totals( root TEXT PRIMARY KEY REFERENCES wf_runs_pool(root) ON DELETE CASCADE, input REAL NOT NULL, input_err REAL NOT NULL, output REAL NOT NULL, output_err REAL NOT NULL, cacheread REAL NOT NULL, cacheread_err REAL NOT NULL, cachewrite REAL NOT NULL, cachewrite_err REAL NOT NULL, cost REAL NOT NULL, cost_err REAL NOT NULL );
CREATE TABLE wf_runs_pool_fence(reason TEXT);
CREATE TABLE wf_runs_fleet_drains( host TEXT PRIMARY KEY, provider_id TEXT, requested_at INTEGER NOT NULL );
CREATE TABLE wf_runs_pool_root_snapshot( root TEXT PRIMARY KEY REFERENCES wf_runs(run_id) ON DELETE CASCADE, epoch INTEGER NOT NULL, snapshot TEXT NOT NULL );
CREATE TABLE wf_runs_work_input_chunks( work TEXT NOT NULL REFERENCES wf_runs_work(id) ON DELETE CASCADE, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(work, idx) );
CREATE TABLE wf_runs_work_result_chunks( work TEXT NOT NULL REFERENCES wf_runs_work_results(work) ON DELETE CASCADE, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(work, idx) );
CREATE TABLE wf_runs_pool_ready( root TEXT PRIMARY KEY REFERENCES wf_runs_pool(root) ON DELETE CASCADE, revision INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE wf_runs_ship_batches( batch TEXT PRIMARY KEY, work TEXT NOT NULL REFERENCES wf_runs_work(id) ON DELETE CASCADE, generation INTEGER NOT NULL, worker TEXT, epoch INTEGER NOT NULL, host TEXT NOT NULL, first_local_seq INTEGER NOT NULL, last_local_seq INTEGER NOT NULL, events INTEGER NOT NULL, shipped_at INTEGER NOT NULL );
CREATE TABLE wf_runs_ship_watermarks( work TEXT PRIMARY KEY REFERENCES wf_runs_work(id) ON DELETE CASCADE, generation INTEGER NOT NULL, host TEXT NOT NULL, last_local_seq INTEGER NOT NULL, last_event_key TEXT NOT NULL, shipped_at INTEGER NOT NULL );
CREATE TABLE wf_runs_pool_shared( root TEXT PRIMARY KEY REFERENCES wf_runs_pool(root) ON DELETE CASCADE, config TEXT NOT NULL, epoch INTEGER NOT NULL, budget_blocked INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE wf_runs_pool_hosts( host TEXT PRIMARY KEY, labels TEXT NOT NULL, git TEXT NOT NULL, restore INTEGER NOT NULL, workers INTEGER NOT NULL, max_workers INTEGER NOT NULL, heartbeat_at INTEGER NOT NULL, roots TEXT NOT NULL DEFAULT '[]', slots_busy INTEGER, draining INTEGER NOT NULL DEFAULT 0, degraded TEXT , provider_id TEXT, journal_schema INTEGER, shipping TEXT, progress TEXT, status_at INTEGER);
CREATE TABLE wf_runs_pool_activity( work TEXT PRIMARY KEY REFERENCES wf_runs_work(id) ON DELETE CASCADE, token TEXT NOT NULL, runs TEXT NOT NULL, version INTEGER NOT NULL );
CREATE TABLE wf_runs_stage_inputs( root TEXT NOT NULL, run_id TEXT NOT NULL, stage_id TEXT NOT NULL, seq INTEGER NOT NULL, work TEXT NOT NULL REFERENCES wf_runs_work(id) ON DELETE CASCADE, kind TEXT NOT NULL, op TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', receipt TEXT, created_at INTEGER NOT NULL, settled_at INTEGER, PRIMARY KEY(root, run_id, stage_id, seq), UNIQUE(root, run_id, stage_id, op) );
CREATE TABLE wf_runs_stage_leases( root TEXT NOT NULL, run_id TEXT NOT NULL, stage_id TEXT NOT NULL, token INTEGER NOT NULL, work TEXT, generation INTEGER, worker TEXT, epoch INTEGER, seq INTEGER, expires_at INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(root, run_id, stage_id) );
CREATE TABLE wf_runs_stage_workspaces( root TEXT NOT NULL, run_id TEXT NOT NULL, stage_id TEXT NOT NULL, work TEXT NOT NULL REFERENCES wf_runs_work(id) ON DELETE CASCADE, generation INTEGER NOT NULL, host TEXT NOT NULL, worktree TEXT NOT NULL, binding TEXT, recorded_at INTEGER NOT NULL, PRIMARY KEY(root, run_id, stage_id) );
CREATE TABLE wf_runs_pool_restore_backoffs( host TEXT NOT NULL, binding TEXT NOT NULL, until INTEGER NOT NULL, failure TEXT NOT NULL, recorded_at INTEGER NOT NULL, PRIMARY KEY(host, binding) );
CREATE TABLE wf_runs_fleet_controller( id INTEGER PRIMARY KEY CHECK(id = 1), holder TEXT NOT NULL, epoch INTEGER NOT NULL, renewed_at INTEGER NOT NULL, lease_ms INTEGER NOT NULL );
CREATE TABLE wf_runs_fleet_events( seq INTEGER PRIMARY KEY, at INTEGER NOT NULL, kind TEXT NOT NULL, target INTEGER, live INTEGER, reason TEXT NOT NULL, error TEXT );
CREATE TABLE wf_runs_rate_buckets( scope TEXT PRIMARY KEY, tat INTEGER NOT NULL, interval_ms REAL NOT NULL, burst INTEGER NOT NULL, cooldown_until INTEGER NOT NULL DEFAULT 0, kind TEXT, updated_at INTEGER , acquired REAL NOT NULL DEFAULT 0, waiting_ms REAL NOT NULL DEFAULT 0, waiting_gc_at INTEGER NOT NULL DEFAULT 0, waiting_epoch INTEGER NOT NULL DEFAULT 0);
CREATE TABLE wf_runs_rate_waiting( scope TEXT NOT NULL, reporter TEXT NOT NULL, total_ms REAL NOT NULL, updated_at INTEGER NOT NULL DEFAULT 0, epoch INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(scope, reporter) );
CREATE TABLE wf_runs_resource_limits(scope TEXT PRIMARY KEY, config TEXT NOT NULL);
CREATE TABLE wf_runs_resource_permits(ticket INTEGER PRIMARY KEY AUTOINCREMENT, operation TEXT UNIQUE NOT NULL, root TEXT NOT NULL, holder TEXT NOT NULL, kind TEXT NOT NULL, state TEXT NOT NULL, reason TEXT, owner TEXT, attempt TEXT, process_identity TEXT, root_epoch INTEGER, granted_at INTEGER);
CREATE TABLE wf_runs_resource_owners(id TEXT PRIMARY KEY, host TEXT NOT NULL, pid INTEGER NOT NULL, expires_at INTEGER NOT NULL, boot TEXT);
CREATE TABLE wf_runs_pool_session_meta (schema_version INTEGER NOT NULL) STRICT;
CREATE TABLE wf_runs_pool_session_sessions ( id TEXT PRIMARY KEY, cwd TEXT NOT NULL, created_at TEXT NOT NULL, header_json TEXT NOT NULL CHECK(json_valid(header_json)), internal INTEGER NOT NULL, last_seq INTEGER NOT NULL, modified_at TEXT NOT NULL, message_count INTEGER NOT NULL, first_message TEXT NOT NULL CHECK(json_valid(first_message)), name TEXT CHECK(name IS NULL OR json_valid(name)), has_name INTEGER NOT NULL, summary TEXT CHECK(summary IS NULL OR json_valid(summary)), summarized_through_id TEXT, summary_state TEXT NOT NULL CHECK(json_valid(summary_state)), revision TEXT NOT NULL DEFAULT '' ) STRICT;
CREATE TABLE wf_runs_pool_session_entries ( session_id TEXT NOT NULL, seq INTEGER NOT NULL, entry_id TEXT NOT NULL, entry_json TEXT NOT NULL CHECK(json_valid(entry_json)), chunks INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(session_id, seq) ) STRICT;
CREATE TABLE wf_runs_pool_session_search_texts ( session_id TEXT NOT NULL, seq INTEGER NOT NULL, text_json TEXT NOT NULL CHECK(json_valid(text_json)), PRIMARY KEY(session_id, seq) ) STRICT;
CREATE TABLE wf_runs_pool_session_blobs ( session_id TEXT NOT NULL, hash TEXT NOT NULL, bytes INTEGER NOT NULL, chunks INTEGER NOT NULL, PRIMARY KEY(session_id, hash) ) STRICT;
CREATE TABLE wf_runs_pool_session_blob_chunks ( session_id TEXT NOT NULL, hash TEXT NOT NULL, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(session_id, hash, idx) ) STRICT;
CREATE TABLE wf_runs_pool_session_entry_chunks ( session_id TEXT NOT NULL, seq INTEGER NOT NULL, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(session_id, seq, idx) ) STRICT;
CREATE TABLE wf_runs_pool_session_open ( session_id TEXT NOT NULL, token TEXT NOT NULL, pid INTEGER NOT NULL, host TEXT NOT NULL, heartbeat_at INTEGER NOT NULL, schema_version INTEGER, PRIMARY KEY(session_id, token) ) STRICT;
CREATE TABLE wf_runs_pool_snapshot_blobs (hash TEXT PRIMARY KEY, bytes INTEGER NOT NULL, data BLOB NOT NULL, created_at INTEGER NOT NULL DEFAULT (unixepoch()), chunks INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE wf_runs_pool_snapshot_run_refs (run_id TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY (run_id, hash)) STRICT, WITHOUT ROWID;
CREATE TABLE wf_runs_pool_snapshot_run_state (run_id TEXT PRIMARY KEY, retained INTEGER NOT NULL, seq INTEGER NOT NULL) STRICT, WITHOUT ROWID;
CREATE TABLE wf_runs_pool_snapshot_session_refs (session_id TEXT NOT NULL, seq INTEGER NOT NULL, root TEXT NOT NULL, snapshot_id TEXT NOT NULL, prev_seq INTEGER, restore_from TEXT, restore_to TEXT, degraded_from TEXT, degraded_since INTEGER, PRIMARY KEY (session_id, seq)) STRICT, WITHOUT ROWID;
CREATE TABLE wf_runs_pool_snapshot_session_links (session_id TEXT NOT NULL, seq INTEGER NOT NULL, entry_id TEXT NOT NULL, parent_id TEXT, anchor_seq INTEGER, children INTEGER NOT NULL, broken INTEGER NOT NULL, PRIMARY KEY (session_id, seq)) STRICT;
CREATE TABLE wf_runs_pool_snapshot_session_records (session_id TEXT NOT NULL, seq INTEGER NOT NULL, snapshot_id TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY (session_id, seq, hash)) STRICT, WITHOUT ROWID;
CREATE TABLE wf_runs_pool_snapshot_carried_refs (owner TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY (owner, hash)) STRICT, WITHOUT ROWID;
CREATE TABLE wf_runs_pool_snapshot_collection (id INTEGER PRIMARY KEY CHECK (id = 1), claimed_at INTEGER, holder TEXT, finished_at INTEGER, deleted INTEGER, error_code TEXT) STRICT;
CREATE TABLE wf_runs_pool_snapshot_index_sources (source TEXT PRIMARY KEY, watermark INTEGER NOT NULL, backfilled_through INTEGER NOT NULL) STRICT, WITHOUT ROWID;
CREATE TABLE wf_runs_pool_snapshot_blob_chunks (hash TEXT NOT NULL, idx INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY (hash, idx)) STRICT;
CREATE TABLE wf_runs_pool_session_search_state (sid INTEGER PRIMARY KEY, session_id TEXT NOT NULL UNIQUE, format INTEGER NOT NULL, indexed_seq INTEGER NOT NULL, revision TEXT NOT NULL, entry_id TEXT NOT NULL) STRICT;
CREATE VIRTUAL TABLE wf_runs_pool_session_search_fts USING fts5(body, content='', contentless_delete=1, tokenize='trigram', detail='none');
