CREATE TRIGGER snapshot_blobs_chunks_delete_all AFTER DELETE ON snapshot_blobs BEGIN DELETE FROM snapshot_blob_chunks WHERE hash = OLD.hash; END;
CREATE TRIGGER session_entries_snapshot_links AFTER INSERT ON session_entries WHEN (SELECT backfilled_through >= watermark FROM snapshot_index_sources WHERE source = 'session-entries') BEGIN /* session-entries@own-progress */ UPDATE snapshot_session_links SET children = children + 1 FROM (SELECT NEW.session_id AS session_id, NEW.seq AS seq, NEW.entry_id AS entry_id, NEW.entry_json AS entry_json, json_extract(NEW.entry_json, '$.parentId') AS parent_id, json_type(NEW.entry_json, '$.parentId') AS parent_type) AS r WHERE snapshot_session_links.session_id = r.session_id AND snapshot_session_links.entry_id = r.parent_id AND r.parent_type = 'text' AND NOT EXISTS (SELECT 1 FROM snapshot_session_links AS own WHERE own.session_id = r.session_id AND own.seq = r.seq); INSERT OR IGNORE INTO snapshot_session_links (session_id, seq, entry_id, parent_id, anchor_seq, children, broken) SELECT r.session_id, r.seq, r.entry_id, CASE WHEN r.parent_type = 'text' THEN r.parent_id END, CASE WHEN instr(r.entry_json, '"worktree_snapshot"') > 0 AND json_extract(r.entry_json, '$.type') = 'worktree_snapshot' AND json_type(r.entry_json, '$.root') = 'text' AND json_type(r.entry_json, '$.snapshotId') = 'text' THEN r.seq ELSE parent.anchor_seq END, 0, CASE WHEN EXISTS (SELECT 1 FROM snapshot_session_links AS other WHERE other.session_id = r.session_id AND other.entry_id = r.entry_id AND other.seq <> r.seq) THEN 1 WHEN r.parent_type IS NULL OR r.parent_type = 'null' THEN 0 WHEN r.parent_type = 'text' AND parent.entry_id IS NOT NULL THEN parent.broken ELSE 1 END FROM (SELECT NEW.session_id AS session_id, NEW.seq AS seq, NEW.entry_id AS entry_id, NEW.entry_json AS entry_json, json_extract(NEW.entry_json, '$.parentId') AS parent_id, json_type(NEW.entry_json, '$.parentId') AS parent_type) AS r LEFT JOIN snapshot_session_links AS parent ON parent.session_id = r.session_id AND parent.entry_id = r.parent_id AND r.parent_type = 'text'; END;
CREATE TRIGGER session_entries_snapshot_refs AFTER INSERT ON session_entries WHEN instr(NEW.entry_json, '"worktree_snapshot"') > 0 AND (SELECT backfilled_through >= watermark FROM snapshot_index_sources WHERE source = 'session-entries') BEGIN /* session-entries@own-progress */ INSERT OR REPLACE INTO snapshot_session_refs (session_id, seq, root, snapshot_id, prev_seq, restore_from, restore_to, degraded_from, degraded_since) SELECT r.session_id, r.seq, json_extract(r.entry_json, '$.root'), json_extract(r.entry_json, '$.snapshotId'), parent.anchor_seq, CASE WHEN json_type(r.entry_json, '$.restore.from') = 'text' AND json_type(r.entry_json, '$.restore.to') = 'text' THEN json_extract(r.entry_json, '$.restore.from') END, CASE WHEN json_type(r.entry_json, '$.restore.from') = 'text' AND json_type(r.entry_json, '$.restore.to') = 'text' THEN json_extract(r.entry_json, '$.restore.to') END, CASE WHEN json_type(r.entry_json, '$.degradedFrom') = 'text' THEN json_extract(r.entry_json, '$.degradedFrom') END, CASE WHEN json_type(r.entry_json, '$.degradedFrom') = 'text' THEN COALESCE((SELECT earlier.degraded_since FROM snapshot_session_refs AS earlier WHERE earlier.session_id = r.session_id AND earlier.seq = parent.anchor_seq AND earlier.degraded_from = json_extract(r.entry_json, '$.degradedFrom')), unixepoch()) END FROM (SELECT NEW.session_id AS session_id, NEW.seq AS seq, NEW.entry_id AS entry_id, NEW.entry_json AS entry_json, json_extract(NEW.entry_json, '$.parentId') AS parent_id, json_type(NEW.entry_json, '$.parentId') AS parent_type) AS r LEFT JOIN snapshot_session_links AS parent ON parent.session_id = r.session_id AND parent.entry_id = r.parent_id AND r.parent_type = 'text' WHERE instr(r.entry_json, '"worktree_snapshot"') > 0 AND json_extract(r.entry_json, '$.type') = 'worktree_snapshot' AND json_type(r.entry_json, '$.root') = 'text' AND json_type(r.entry_json, '$.snapshotId') = 'text'; INSERT OR IGNORE INTO snapshot_session_records (session_id, seq, snapshot_id, hash) SELECT r.session_id, r.seq, json_extract(r.entry_json, '$.snapshotId'), json_extract(r.entry_json, link.fullkey || '.patch') FROM (SELECT NEW.session_id AS session_id, NEW.seq AS seq, NEW.entry_id AS entry_id, NEW.entry_json AS entry_json, json_extract(NEW.entry_json, '$.parentId') AS parent_id, json_type(NEW.entry_json, '$.parentId') AS parent_type) AS r, json_each(r.entry_json, '$.snapshot.chain') AS link WHERE typeof(json_extract(r.entry_json, link.fullkey || '.patch')) = 'text' AND instr(r.entry_json, '"worktree_snapshot"') > 0 AND json_extract(r.entry_json, '$.type') = 'worktree_snapshot' AND json_type(r.entry_json, '$.root') = 'text' AND json_type(r.entry_json, '$.snapshotId') = 'text'; INSERT OR IGNORE INTO snapshot_session_records (session_id, seq, snapshot_id, hash) SELECT r.session_id, r.seq, json_extract(r.entry_json, '$.snapshotId'), json_extract(r.entry_json, '$.snapshot.bundle.blob') FROM (SELECT NEW.session_id AS session_id, NEW.seq AS seq, NEW.entry_id AS entry_id, NEW.entry_json AS entry_json, json_extract(NEW.entry_json, '$.parentId') AS parent_id, json_type(NEW.entry_json, '$.parentId') AS parent_type) AS r WHERE typeof(json_extract(r.entry_json, '$.snapshot.bundle.blob')) = 'text' AND instr(r.entry_json, '"worktree_snapshot"') > 0 AND json_extract(r.entry_json, '$.type') = 'worktree_snapshot' AND json_type(r.entry_json, '$.root') = 'text' AND json_type(r.entry_json, '$.snapshotId') = 'text'; END;
CREATE TRIGGER session_entries_snapshot_pending AFTER INSERT ON session_entries WHEN NOT COALESCE((SELECT backfilled_through >= watermark FROM snapshot_index_sources WHERE source = 'session-entries'), 1) BEGIN /* session-entries@own-progress */ UPDATE snapshot_index_sources SET watermark = NEW.rowid WHERE source = 'session-entries' AND watermark < NEW.rowid; UPDATE snapshot_index_sources SET backfilled_through = NEW.rowid - 1 WHERE source = 'session-entries' AND backfilled_through >= NEW.rowid; UPDATE snapshot_index_sources SET watermark = NEW.rowid WHERE source = 'session-entries@own-progress' AND watermark < NEW.rowid; UPDATE snapshot_index_sources SET backfilled_through = NEW.rowid - 1 WHERE source = 'session-entries@own-progress' AND backfilled_through >= NEW.rowid; END;
CREATE TRIGGER session_entries_snapshot_refs_delete AFTER DELETE ON session_entries BEGIN /* session-entries@own-progress */ UPDATE snapshot_session_links SET children = children - 1 WHERE session_id = OLD.session_id AND children > 0 AND entry_id = (SELECT parent_id FROM snapshot_session_links WHERE session_id = OLD.session_id AND seq = OLD.seq); DELETE FROM snapshot_session_links WHERE session_id = OLD.session_id AND seq = OLD.seq; DELETE FROM snapshot_session_refs WHERE session_id = OLD.session_id AND seq = OLD.seq; DELETE FROM snapshot_session_records WHERE session_id = OLD.session_id AND seq = OLD.seq; END;
CREATE TRIGGER wf_events_snapshot_refs AFTER INSERT ON wf_events WHEN NEW.type = 'CheckpointRecorded' AND instr(NEW.payload, '"worktreeSnapshots"') > 0 AND CASE WHEN json_valid(NEW.payload) THEN (json_extract(NEW.payload, '$.kind') IN ('tool', 'stage')) ELSE 0 END BEGIN INSERT OR IGNORE INTO snapshot_run_refs (run_id, hash) SELECT r.run_id, json_extract(r.payload, link.fullkey || '.patch') FROM (SELECT NEW.run_id AS run_id, NEW.seq AS seq, NEW.payload AS payload) AS r, json_each(r.payload, '$.worktreeSnapshots') AS snapshot, json_each(r.payload, snapshot.fullkey || '.chain') AS link WHERE typeof(json_extract(r.payload, link.fullkey || '.patch')) = 'text'; INSERT OR IGNORE INTO snapshot_run_refs (run_id, hash) SELECT r.run_id, json_extract(r.payload, snapshot.fullkey || '.bundle.blob') FROM (SELECT NEW.run_id AS run_id, NEW.seq AS seq, NEW.payload AS payload) AS r, json_each(r.payload, '$.worktreeSnapshots') AS snapshot WHERE typeof(json_extract(r.payload, snapshot.fullkey || '.bundle.blob')) = 'text'; END;
CREATE TRIGGER wf_events_snapshot_state AFTER INSERT ON wf_events WHEN NEW.type IN ('RunStarted', 'StatusChanged') AND CASE WHEN json_valid(NEW.payload) THEN (json_type(NEW.payload, '$.workflowId') = 'text' AND json_type(NEW.payload, '$.status') = 'text' AND json_type(NEW.payload, '$.completedCheckpoints') IN ('integer', 'real') AND json_type(NEW.payload, '$.pendingPrompts') IN ('integer', 'real')) ELSE 0 END BEGIN INSERT INTO snapshot_run_state (run_id, retained, seq) SELECT r.run_id, CASE WHEN json_type(r.payload, '$.rootWorkflowId') IS NOT NULL AND (json_type(r.payload, '$.rootWorkflowId') <> 'text' OR json_extract(r.payload, '$.rootWorkflowId') <> json_extract(r.payload, '$.workflowId')) THEN 0 WHEN json_extract(r.payload, '$.status') IN ('failed', 'blocked', 'running', 'paused') THEN json_type(r.payload, '$.resumable') IS NOT 'false' ELSE 0 END, r.seq FROM (SELECT NEW.run_id AS run_id, NEW.seq AS seq, NEW.payload AS payload) AS r WHERE true ON CONFLICT (run_id) DO UPDATE SET retained = excluded.retained, seq = excluded.seq WHERE excluded.seq >= snapshot_run_state.seq; END;
CREATE TRIGGER wf_runs_snapshot_state_insert AFTER INSERT ON wf_runs BEGIN INSERT INTO snapshot_run_state (run_id, retained, seq) SELECT r.run_id, r.status NOT IN ('completed', 'cancelled'), -1 FROM (SELECT NEW.run_id AS run_id, NEW.status AS status) AS r WHERE true ON CONFLICT (run_id) DO NOTHING; END;
CREATE TRIGGER wf_runs_snapshot_state_status AFTER UPDATE OF status ON wf_runs BEGIN UPDATE snapshot_run_state SET retained = NEW.status NOT IN ('completed', 'cancelled') WHERE run_id = NEW.run_id AND seq = -1; END;
CREATE TRIGGER wf_runs_snapshot_refs_delete AFTER DELETE ON wf_runs BEGIN DELETE FROM snapshot_run_refs WHERE run_id = OLD.run_id; DELETE FROM snapshot_run_state WHERE run_id = OLD.run_id; END;
CREATE TRIGGER wf_runs_pool_usage_totals_insert AFTER INSERT ON wf_runs_pool_usage BEGIN UPDATE wf_runs_pool_usage_totals SET input = input + (NEW.input), input_err = input_err + CASE WHEN abs(input) > abs((NEW.input)) THEN (input - (input + (NEW.input))) + (NEW.input) ELSE ((NEW.input) - (input + (NEW.input))) + input END, output = output + (NEW.output), output_err = output_err + CASE WHEN abs(output) > abs((NEW.output)) THEN (output - (output + (NEW.output))) + (NEW.output) ELSE ((NEW.output) - (output + (NEW.output))) + output END, cacheread = cacheread + (NEW.cacheread), cacheread_err = cacheread_err + CASE WHEN abs(cacheread) > abs((NEW.cacheread)) THEN (cacheread - (cacheread + (NEW.cacheread))) + (NEW.cacheread) ELSE ((NEW.cacheread) - (cacheread + (NEW.cacheread))) + cacheread END, cachewrite = cachewrite + (NEW.cachewrite), cachewrite_err = cachewrite_err + CASE WHEN abs(cachewrite) > abs((NEW.cachewrite)) THEN (cachewrite - (cachewrite + (NEW.cachewrite))) + (NEW.cachewrite) ELSE ((NEW.cachewrite) - (cachewrite + (NEW.cachewrite))) + cachewrite END, cost = cost + (NEW.cost), cost_err = cost_err + CASE WHEN abs(cost) > abs((NEW.cost)) THEN (cost - (cost + (NEW.cost))) + (NEW.cost) ELSE ((NEW.cost) - (cost + (NEW.cost))) + cost END WHERE root = (SELECT root FROM wf_runs_work WHERE id = NEW.work); END;
CREATE TRIGGER wf_runs_pool_usage_totals_update AFTER UPDATE ON wf_runs_pool_usage WHEN OLD.input IS NOT NEW.input OR OLD.output IS NOT NEW.output OR OLD.cacheread IS NOT NEW.cacheread OR OLD.cachewrite IS NOT NEW.cachewrite OR OLD.cost IS NOT NEW.cost OR OLD.work IS NOT NEW.work BEGIN UPDATE wf_runs_pool_usage_totals SET input = input + (-OLD.input), input_err = input_err + CASE WHEN abs(input) > abs((-OLD.input)) THEN (input - (input + (-OLD.input))) + (-OLD.input) ELSE ((-OLD.input) - (input + (-OLD.input))) + input END, output = output + (-OLD.output), output_err = output_err + CASE WHEN abs(output) > abs((-OLD.output)) THEN (output - (output + (-OLD.output))) + (-OLD.output) ELSE ((-OLD.output) - (output + (-OLD.output))) + output END, cacheread = cacheread + (-OLD.cacheread), cacheread_err = cacheread_err + CASE WHEN abs(cacheread) > abs((-OLD.cacheread)) THEN (cacheread - (cacheread + (-OLD.cacheread))) + (-OLD.cacheread) ELSE ((-OLD.cacheread) - (cacheread + (-OLD.cacheread))) + cacheread END, cachewrite = cachewrite + (-OLD.cachewrite), cachewrite_err = cachewrite_err + CASE WHEN abs(cachewrite) > abs((-OLD.cachewrite)) THEN (cachewrite - (cachewrite + (-OLD.cachewrite))) + (-OLD.cachewrite) ELSE ((-OLD.cachewrite) - (cachewrite + (-OLD.cachewrite))) + cachewrite END, cost = cost + (-OLD.cost), cost_err = cost_err + CASE WHEN abs(cost) > abs((-OLD.cost)) THEN (cost - (cost + (-OLD.cost))) + (-OLD.cost) ELSE ((-OLD.cost) - (cost + (-OLD.cost))) + cost END WHERE root = (SELECT root FROM wf_runs_work WHERE id = OLD.work); UPDATE wf_runs_pool_usage_totals SET input = input + (NEW.input), input_err = input_err + CASE WHEN abs(input) > abs((NEW.input)) THEN (input - (input + (NEW.input))) + (NEW.input) ELSE ((NEW.input) - (input + (NEW.input))) + input END, output = output + (NEW.output), output_err = output_err + CASE WHEN abs(output) > abs((NEW.output)) THEN (output - (output + (NEW.output))) + (NEW.output) ELSE ((NEW.output) - (output + (NEW.output))) + output END, cacheread = cacheread + (NEW.cacheread), cacheread_err = cacheread_err + CASE WHEN abs(cacheread) > abs((NEW.cacheread)) THEN (cacheread - (cacheread + (NEW.cacheread))) + (NEW.cacheread) ELSE ((NEW.cacheread) - (cacheread + (NEW.cacheread))) + cacheread END, cachewrite = cachewrite + (NEW.cachewrite), cachewrite_err = cachewrite_err + CASE WHEN abs(cachewrite) > abs((NEW.cachewrite)) THEN (cachewrite - (cachewrite + (NEW.cachewrite))) + (NEW.cachewrite) ELSE ((NEW.cachewrite) - (cachewrite + (NEW.cachewrite))) + cachewrite END, cost = cost + (NEW.cost), cost_err = cost_err + CASE WHEN abs(cost) > abs((NEW.cost)) THEN (cost - (cost + (NEW.cost))) + (NEW.cost) ELSE ((NEW.cost) - (cost + (NEW.cost))) + cost END WHERE root = (SELECT root FROM wf_runs_work WHERE id = NEW.work); END;
CREATE TRIGGER wf_runs_pool_usage_totals_delete AFTER DELETE ON wf_runs_pool_usage BEGIN DELETE FROM wf_runs_pool_usage_totals WHERE root = (SELECT root FROM wf_runs_work WHERE id = OLD.work); END;
CREATE TRIGGER wf_runs_pool_usage_totals_work_delete BEFORE DELETE ON wf_runs_work BEGIN DELETE FROM wf_runs_pool_usage_totals WHERE root = OLD.root; END;
CREATE TRIGGER wf_runs_pool_fence_abort BEFORE INSERT ON wf_runs_pool_fence BEGIN SELECT RAISE(ABORT, 'atomic-pool-fence'); END;
CREATE TRIGGER wf_runs_pool_ready_insert AFTER INSERT ON wf_runs_work WHEN NEW.state = 'ready' BEGIN INSERT INTO wf_runs_pool_ready(root, revision) VALUES (NEW.root, 1) ON CONFLICT(root) DO UPDATE SET revision = revision + 1; END;
CREATE TRIGGER wf_runs_pool_ready_update AFTER UPDATE ON wf_runs_work WHEN NEW.state = 'ready' BEGIN INSERT INTO wf_runs_pool_ready(root, revision) VALUES (NEW.root, 1) ON CONFLICT(root) DO UPDATE SET revision = revision + 1; END;
CREATE TRIGGER wf_runs_pool_snapshot_blobs_chunks_delete_all AFTER DELETE ON wf_runs_pool_snapshot_blobs BEGIN DELETE FROM wf_runs_pool_snapshot_blob_chunks WHERE hash = OLD.hash; END;
CREATE TRIGGER wf_runs_pool_session_entries_snapshot_links AFTER INSERT ON wf_runs_pool_session_entries WHEN (SELECT backfilled_through >= watermark FROM wf_runs_pool_snapshot_index_sources WHERE source = 'session-entries') BEGIN /* session-entries@own-progress */ UPDATE wf_runs_pool_snapshot_session_links SET children = children + 1 FROM (SELECT NEW.session_id AS session_id, NEW.seq AS seq, NEW.entry_id AS entry_id, NEW.entry_json AS entry_json, json_extract(NEW.entry_json, '$.parentId') AS parent_id, json_type(NEW.entry_json, '$.parentId') AS parent_type) AS r WHERE wf_runs_pool_snapshot_session_links.session_id = r.session_id AND wf_runs_pool_snapshot_session_links.entry_id = r.parent_id AND r.parent_type = 'text' AND NOT EXISTS (SELECT 1 FROM wf_runs_pool_snapshot_session_links AS own WHERE own.session_id = r.session_id AND own.seq = r.seq); INSERT OR IGNORE INTO wf_runs_pool_snapshot_session_links (session_id, seq, entry_id, parent_id, anchor_seq, children, broken) SELECT r.session_id, r.seq, r.entry_id, CASE WHEN r.parent_type = 'text' THEN r.parent_id END, CASE WHEN instr(r.entry_json, '"worktree_snapshot"') > 0 AND json_extract(r.entry_json, '$.type') = 'worktree_snapshot' AND json_type(r.entry_json, '$.root') = 'text' AND json_type(r.entry_json, '$.snapshotId') = 'text' THEN r.seq ELSE parent.anchor_seq END, 0, CASE WHEN EXISTS (SELECT 1 FROM wf_runs_pool_snapshot_session_links AS other WHERE other.session_id = r.session_id AND other.entry_id = r.entry_id AND other.seq <> r.seq) THEN 1 WHEN r.parent_type IS NULL OR r.parent_type = 'null' THEN 0 WHEN r.parent_type = 'text' AND parent.entry_id IS NOT NULL THEN parent.broken ELSE 1 END FROM (SELECT NEW.session_id AS session_id, NEW.seq AS seq, NEW.entry_id AS entry_id, NEW.entry_json AS entry_json, json_extract(NEW.entry_json, '$.parentId') AS parent_id, json_type(NEW.entry_json, '$.parentId') AS parent_type) AS r LEFT JOIN wf_runs_pool_snapshot_session_links AS parent ON parent.session_id = r.session_id AND parent.entry_id = r.parent_id AND r.parent_type = 'text'; END;
CREATE TRIGGER wf_runs_pool_session_entries_snapshot_refs AFTER INSERT ON wf_runs_pool_session_entries WHEN instr(NEW.entry_json, '"worktree_snapshot"') > 0 AND (SELECT backfilled_through >= watermark FROM wf_runs_pool_snapshot_index_sources WHERE source = 'session-entries') BEGIN /* session-entries@own-progress */ INSERT OR REPLACE INTO wf_runs_pool_snapshot_session_refs (session_id, seq, root, snapshot_id, prev_seq, restore_from, restore_to, degraded_from, degraded_since) SELECT r.session_id, r.seq, json_extract(r.entry_json, '$.root'), json_extract(r.entry_json, '$.snapshotId'), parent.anchor_seq, CASE WHEN json_type(r.entry_json, '$.restore.from') = 'text' AND json_type(r.entry_json, '$.restore.to') = 'text' THEN json_extract(r.entry_json, '$.restore.from') END, CASE WHEN json_type(r.entry_json, '$.restore.from') = 'text' AND json_type(r.entry_json, '$.restore.to') = 'text' THEN json_extract(r.entry_json, '$.restore.to') END, CASE WHEN json_type(r.entry_json, '$.degradedFrom') = 'text' THEN json_extract(r.entry_json, '$.degradedFrom') END, CASE WHEN json_type(r.entry_json, '$.degradedFrom') = 'text' THEN COALESCE((SELECT earlier.degraded_since FROM wf_runs_pool_snapshot_session_refs AS earlier WHERE earlier.session_id = r.session_id AND earlier.seq = parent.anchor_seq AND earlier.degraded_from = json_extract(r.entry_json, '$.degradedFrom')), unixepoch()) END FROM (SELECT NEW.session_id AS session_id, NEW.seq AS seq, NEW.entry_id AS entry_id, NEW.entry_json AS entry_json, json_extract(NEW.entry_json, '$.parentId') AS parent_id, json_type(NEW.entry_json, '$.parentId') AS parent_type) AS r LEFT JOIN wf_runs_pool_snapshot_session_links AS parent ON parent.session_id = r.session_id AND parent.entry_id = r.parent_id AND r.parent_type = 'text' WHERE instr(r.entry_json, '"worktree_snapshot"') > 0 AND json_extract(r.entry_json, '$.type') = 'worktree_snapshot' AND json_type(r.entry_json, '$.root') = 'text' AND json_type(r.entry_json, '$.snapshotId') = 'text'; INSERT OR IGNORE INTO wf_runs_pool_snapshot_session_records (session_id, seq, snapshot_id, hash) SELECT r.session_id, r.seq, json_extract(r.entry_json, '$.snapshotId'), json_extract(r.entry_json, link.fullkey || '.patch') FROM (SELECT NEW.session_id AS session_id, NEW.seq AS seq, NEW.entry_id AS entry_id, NEW.entry_json AS entry_json, json_extract(NEW.entry_json, '$.parentId') AS parent_id, json_type(NEW.entry_json, '$.parentId') AS parent_type) AS r, json_each(r.entry_json, '$.snapshot.chain') AS link WHERE typeof(json_extract(r.entry_json, link.fullkey || '.patch')) = 'text' AND instr(r.entry_json, '"worktree_snapshot"') > 0 AND json_extract(r.entry_json, '$.type') = 'worktree_snapshot' AND json_type(r.entry_json, '$.root') = 'text' AND json_type(r.entry_json, '$.snapshotId') = 'text'; INSERT OR IGNORE INTO wf_runs_pool_snapshot_session_records (session_id, seq, snapshot_id, hash) SELECT r.session_id, r.seq, json_extract(r.entry_json, '$.snapshotId'), json_extract(r.entry_json, '$.snapshot.bundle.blob') FROM (SELECT NEW.session_id AS session_id, NEW.seq AS seq, NEW.entry_id AS entry_id, NEW.entry_json AS entry_json, json_extract(NEW.entry_json, '$.parentId') AS parent_id, json_type(NEW.entry_json, '$.parentId') AS parent_type) AS r WHERE typeof(json_extract(r.entry_json, '$.snapshot.bundle.blob')) = 'text' AND instr(r.entry_json, '"worktree_snapshot"') > 0 AND json_extract(r.entry_json, '$.type') = 'worktree_snapshot' AND json_type(r.entry_json, '$.root') = 'text' AND json_type(r.entry_json, '$.snapshotId') = 'text'; END;
CREATE TRIGGER wf_runs_pool_session_entries_snapshot_pending AFTER INSERT ON wf_runs_pool_session_entries WHEN NOT COALESCE((SELECT backfilled_through >= watermark FROM wf_runs_pool_snapshot_index_sources WHERE source = 'session-entries'), 1) BEGIN /* session-entries@own-progress */ UPDATE wf_runs_pool_snapshot_index_sources SET watermark = NEW.rowid WHERE source = 'session-entries' AND watermark < NEW.rowid; UPDATE wf_runs_pool_snapshot_index_sources SET backfilled_through = NEW.rowid - 1 WHERE source = 'session-entries' AND backfilled_through >= NEW.rowid; UPDATE wf_runs_pool_snapshot_index_sources SET watermark = NEW.rowid WHERE source = 'session-entries@own-progress' AND watermark < NEW.rowid; UPDATE wf_runs_pool_snapshot_index_sources SET backfilled_through = NEW.rowid - 1 WHERE source = 'session-entries@own-progress' AND backfilled_through >= NEW.rowid; END;
CREATE TRIGGER wf_runs_pool_session_entries_snapshot_refs_delete AFTER DELETE ON wf_runs_pool_session_entries BEGIN /* session-entries@own-progress */ UPDATE wf_runs_pool_snapshot_session_links SET children = children - 1 WHERE session_id = OLD.session_id AND children > 0 AND entry_id = (SELECT parent_id FROM wf_runs_pool_snapshot_session_links WHERE session_id = OLD.session_id AND seq = OLD.seq); DELETE FROM wf_runs_pool_snapshot_session_links WHERE session_id = OLD.session_id AND seq = OLD.seq; DELETE FROM wf_runs_pool_snapshot_session_refs WHERE session_id = OLD.session_id AND seq = OLD.seq; DELETE FROM wf_runs_pool_snapshot_session_records WHERE session_id = OLD.session_id AND seq = OLD.seq; END;
CREATE TRIGGER wf_runs_work_snapshot_carried_insert AFTER INSERT ON wf_runs_work WHEN instr(NEW.descriptor, '"workspaceSnapshot"') > 0 BEGIN INSERT OR IGNORE INTO snapshot_carried_refs (owner, hash) SELECT DISTINCT r.owner, json_extract(r.snapshot, link.fullkey || '.patch') FROM (SELECT 'work:' || NEW.id AS owner, CASE WHEN json_valid(NEW.descriptor) THEN NEW.descriptor ELSE '{}' END AS snapshot) AS r, json_each(r.snapshot, '$.execution.workspaceSnapshot.chain') AS link WHERE typeof(json_extract(r.snapshot, link.fullkey || '.patch')) = 'text' AND NOT EXISTS (SELECT 1 FROM snapshot_carried_refs AS held WHERE held.owner = r.owner AND held.hash = json_extract(r.snapshot, link.fullkey || '.patch')); INSERT OR IGNORE INTO snapshot_carried_refs (owner, hash) SELECT DISTINCT r.owner, json_extract(r.snapshot, '$.execution.workspaceSnapshot.bundle.blob') FROM (SELECT 'work:' || NEW.id AS owner, CASE WHEN json_valid(NEW.descriptor) THEN NEW.descriptor ELSE '{}' END AS snapshot) AS r WHERE typeof(json_extract(r.snapshot, '$.execution.workspaceSnapshot.bundle.blob')) = 'text' AND NOT EXISTS (SELECT 1 FROM snapshot_carried_refs AS held WHERE held.owner = r.owner AND held.hash = json_extract(r.snapshot, '$.execution.workspaceSnapshot.bundle.blob')); END;
CREATE TRIGGER wf_runs_work_snapshot_carried_update AFTER UPDATE OF descriptor ON wf_runs_work WHEN instr(OLD.descriptor, '"workspaceSnapshot"') > 0 OR instr(NEW.descriptor, '"workspaceSnapshot"') > 0 BEGIN DELETE FROM snapshot_carried_refs WHERE owner = 'work:' || OLD.id; INSERT OR IGNORE INTO snapshot_carried_refs (owner, hash) SELECT DISTINCT r.owner, json_extract(r.snapshot, link.fullkey || '.patch') FROM (SELECT 'work:' || NEW.id AS owner, CASE WHEN json_valid(NEW.descriptor) THEN NEW.descriptor ELSE '{}' END AS snapshot) AS r, json_each(r.snapshot, '$.execution.workspaceSnapshot.chain') AS link WHERE typeof(json_extract(r.snapshot, link.fullkey || '.patch')) = 'text' AND NOT EXISTS (SELECT 1 FROM snapshot_carried_refs AS held WHERE held.owner = r.owner AND held.hash = json_extract(r.snapshot, link.fullkey || '.patch')); INSERT OR IGNORE INTO snapshot_carried_refs (owner, hash) SELECT DISTINCT r.owner, json_extract(r.snapshot, '$.execution.workspaceSnapshot.bundle.blob') FROM (SELECT 'work:' || NEW.id AS owner, CASE WHEN json_valid(NEW.descriptor) THEN NEW.descriptor ELSE '{}' END AS snapshot) AS r WHERE typeof(json_extract(r.snapshot, '$.execution.workspaceSnapshot.bundle.blob')) = 'text' AND NOT EXISTS (SELECT 1 FROM snapshot_carried_refs AS held WHERE held.owner = r.owner AND held.hash = json_extract(r.snapshot, '$.execution.workspaceSnapshot.bundle.blob')); END;
CREATE TRIGGER wf_runs_work_snapshot_carried_delete AFTER DELETE ON wf_runs_work WHEN instr(OLD.descriptor, '"workspaceSnapshot"') > 0 BEGIN DELETE FROM snapshot_carried_refs WHERE owner = 'work:' || OLD.id; END;
CREATE TRIGGER wf_runs_pool_root_snapshot_snapshot_carried_insert AFTER INSERT ON wf_runs_pool_root_snapshot BEGIN INSERT OR IGNORE INTO snapshot_carried_refs (owner, hash) SELECT DISTINCT r.owner, json_extract(r.snapshot, link.fullkey || '.patch') FROM (SELECT 'root:' || NEW.root AS owner, CASE WHEN json_valid(NEW.snapshot) THEN NEW.snapshot ELSE '{}' END AS snapshot) AS r, json_each(r.snapshot, '$.chain') AS link WHERE typeof(json_extract(r.snapshot, link.fullkey || '.patch')) = 'text' AND NOT EXISTS (SELECT 1 FROM snapshot_carried_refs AS held WHERE held.owner = r.owner AND held.hash = json_extract(r.snapshot, link.fullkey || '.patch')); INSERT OR IGNORE INTO snapshot_carried_refs (owner, hash) SELECT DISTINCT r.owner, json_extract(r.snapshot, '$.bundle.blob') FROM (SELECT 'root:' || NEW.root AS owner, CASE WHEN json_valid(NEW.snapshot) THEN NEW.snapshot ELSE '{}' END AS snapshot) AS r WHERE typeof(json_extract(r.snapshot, '$.bundle.blob')) = 'text' AND NOT EXISTS (SELECT 1 FROM snapshot_carried_refs AS held WHERE held.owner = r.owner AND held.hash = json_extract(r.snapshot, '$.bundle.blob')); END;
CREATE TRIGGER wf_runs_pool_root_snapshot_snapshot_carried_update AFTER UPDATE OF snapshot ON wf_runs_pool_root_snapshot BEGIN DELETE FROM snapshot_carried_refs WHERE owner = 'root:' || OLD.root; INSERT OR IGNORE INTO snapshot_carried_refs (owner, hash) SELECT DISTINCT r.owner, json_extract(r.snapshot, link.fullkey || '.patch') FROM (SELECT 'root:' || NEW.root AS owner, CASE WHEN json_valid(NEW.snapshot) THEN NEW.snapshot ELSE '{}' END AS snapshot) AS r, json_each(r.snapshot, '$.chain') AS link WHERE typeof(json_extract(r.snapshot, link.fullkey || '.patch')) = 'text' AND NOT EXISTS (SELECT 1 FROM snapshot_carried_refs AS held WHERE held.owner = r.owner AND held.hash = json_extract(r.snapshot, link.fullkey || '.patch')); INSERT OR IGNORE INTO snapshot_carried_refs (owner, hash) SELECT DISTINCT r.owner, json_extract(r.snapshot, '$.bundle.blob') FROM (SELECT 'root:' || NEW.root AS owner, CASE WHEN json_valid(NEW.snapshot) THEN NEW.snapshot ELSE '{}' END AS snapshot) AS r WHERE typeof(json_extract(r.snapshot, '$.bundle.blob')) = 'text' AND NOT EXISTS (SELECT 1 FROM snapshot_carried_refs AS held WHERE held.owner = r.owner AND held.hash = json_extract(r.snapshot, '$.bundle.blob')); END;
CREATE TRIGGER wf_runs_pool_root_snapshot_snapshot_carried_delete AFTER DELETE ON wf_runs_pool_root_snapshot BEGIN DELETE FROM snapshot_carried_refs WHERE owner = 'root:' || OLD.root; END;
